import "../styles/Videos.css";
import { useEffect, useState } from "react";
import { getVideos } from "../services/videoService";

function Videos() {

    const [clips, setClips] = useState([]);
    const [fullStreams, setFullStreams] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(function() {

        async function loadVideos() {
            try {
                const data = await getVideos();
                setClips(data.clips);
                setFullStreams(data.fullStreams);
            } catch (error) {
                console.log("Error loading videos");
            } finally {
                setLoading(false);
            }
        }

        loadVideos();

    }, []);

    return (
        <div className="videos-page">

            <div className="page-header">
                <h1>Videos</h1>

                <p className="page-text">
                    Highlights and moments from the BLAndrew575 stream.
                </p>
            </div>

            <div className="gold-line"></div>

            {loading ? (
                <p className="videos-loading">Loading videos...</p>
            ) : (
                <>

                    <div className="video-section-top">
                        <h2 className="video-section-title">
                            Featured Clips
                        </h2>

                        <a
                            className="video-link-button"
                            href="https://www.twitch.tv/blandrew575/videos?featured=true&filter=clips&range=30d"
                            target="_blank"
                            rel="noreferrer"
                        >
                            🎬 More Clips
                        </a>
                    </div>

                    <div className="video-grid">
                        {clips.map(function(video) {
                            return (
                                <div key={video.id} className="video-card">

                                    <div className="video-wrapper">
                                        <iframe
                                            src={video.src}
                                            allowFullScreen
                                            title={video.title}
                                        ></iframe>
                                    </div>

                                    <div className="video-title-row">
                                        <p className="video-title">
                                            {video.title}
                                        </p>

                                        <span className="video-date">
                                            {video.date}
                                        </span>
                                    </div>

                                </div>
                            );
                        })}
                    </div>


                    <div className="video-section-top">
                        <h2 className="video-section-title">
                            Full Streams
                        </h2>

                        <a
                            className="video-link-button"
                            href="https://www.twitch.tv/blandrew575/videos?filter=archives&sort=time"
                            target="_blank"
                            rel="noreferrer"
                        >
                            📺 More Streams
                        </a>
                    </div>

                    <div className="video-grid">
                        {fullStreams.map(function(video) {
                            return (
                                <div key={video.id} className="video-card">

                                    <div className="video-wrapper">
                                        <iframe
                                            src={video.src}
                                            allowFullScreen
                                            title={video.title}
                                        ></iframe>
                                    </div>

                                    <div className="video-title-row">
                                        <p className="video-title">
                                            {video.title}
                                        </p>

                                        <span className="video-date">
                                            {video.date}
                                        </span>
                                    </div>

                                </div>
                            );
                        })}
                    </div>

                </>
            )}

        </div>
    );
}

export default Videos;
